## 5. Adversarial tests

### `tests/run_tests.sh`

```bash
#!/usr/bin/env bash
# Adversarial tests for walrec.sh. Pure shell; no external test framework.
set -uo pipefail
HERE="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
W="$HERE/../walrec.sh"
TMP="$(mktemp -d "${TMPDIR:-/tmp}/walrec-tests.XXXXXX")"
trap 'rm -rf "$TMP"' EXIT
pass=0; fail=0
ok()  { pass=$((pass + 1)); printf 'ok   - %s\n' "$1"; }
bad() { fail=$((fail + 1)); printf 'FAIL - %s\n' "$1"; }
mk() { "$W" mkrec "$2" "$3" "$4" "$5" "$6" "$7" "$8" >> "$1"; }
check() {
    local mod="$1" erc="$2" estate="$3"; shift 3
    local got rc
    got="$("$W" --mod "$mod" --check "$@" 2>/dev/null)"; rc=$?
    if [ "$rc" != "$erc" ]; then bad "$CASE (rc=$rc want $erc)"; return 1; fi
    if [ "$got" != "$estate" ]; then bad "$CASE (state mismatch)"; return 1; fi
    ok "$CASE"
}
expect_rc() {
    local mod="$1" erc="$2"; shift 2
    "$W" --mod "$mod" --check "$@" >/dev/null 2>&1
    local rc=$?; if [ "$rc" = "$erc" ]; then ok "$CASE"; else bad "$CASE (rc=$rc want $erc)"; fi
}
CASE="clean commit order with dependencies"
{ d="$TMP/clean"; mkdir -p "$d"
  for s in a b; do
    mk "$d/$s.log" 0 T1 "$s" PREPARE - - -; mk "$d/$s.log" 1 T1 "$s" COMMIT - 0 -
    mk "$d/$s.log" 2 T2 "$s" PREPARE - - -; mk "$d/$s.log" 3 T2 "$s" COMMIT - 1 -
    mk "$d/$s.log" 4 T3 "$s" PREPARE - - -; mk "$d/$s.log" 5 T3 "$s" COMMIT - 2 -; done
  mk "$d/a.log" 6 T3 a DATA - - x
  check 65536 0 $'0\tT1\t\t\n1\tT2\t\t\n2\tT3\t\tx;' "$d/a.log" "$d/b.log"; }
CASE="torn COMMIT on one participant rolls the txn back"
{ d="$TMP/torn"; mkdir -p "$d"
  for s in a b; do
    mk "$d/$s.log" 0 T1 "$s" PREPARE - - -; mk "$d/$s.log" 1 T1 "$s" COMMIT - 0 -
    mk "$d/$s.log" 2 T2 "$s" PREPARE - - -; mk "$d/$s.log" 3 T2 "$s" COMMIT - 1 -; done
  sz=$(stat -c%s "$d/b.log"); truncate -s $((sz - 15)) "$d/b.log"
  check 65536 0 $'0\tT1\t\t' "$d/a.log" "$d/b.log"; }
CASE="physical duplicate (same shard+seq) is dropped"
{ d="$TMP/dupphys"; mkdir -p "$d"; mk "$d/a.log" 0 T1 a COMMIT - 5 -
  tail -n1 "$d/a.log" >> "$d/a.log"; check 65536 0 $'5\tT1\t\t' "$d/a.log"; }
CASE="logical duplicate (retransmit at new seq) is dropped"
{ d="$TMP/duplog"; mkdir -p "$d"
  mk "$d/a.log" 0 T1 a COMMIT - 5 -; mk "$d/a.log" 1 T1 a COMMIT - 5 -
  check 65536 0 $'5\tT1\t\t' "$d/a.log"; }
CASE="conflicting duplicate (same shard+seq, different content) is rejected"
{ d="$TMP/confdup"; mkdir -p "$d"
  mk "$d/a.log" 0 T1 a COMMIT - 5 -; mk "$d/a.log" 0 T2 a COMMIT - 6 -
  expect_rc 65536 1 "$d/a.log"; }
CASE="per-shard sequence wraparound is accepted"
{ d="$TMP/seqwrap"; mkdir -p "$d"
  mk "$d/a.log" 6 T1 a PREPARE - - -; mk "$d/a.log" 7 T1 a COMMIT - 6 -
  mk "$d/a.log" 0 T2 a PREPARE - - -; mk "$d/a.log" 1 T2 a COMMIT - 7 -
  check 8 0 $'6\tT1\t\t\n7\tT2\t\t' "$d/a.log"; }
CASE="commit-sequence wraparound orders correctly"
{ d="$TMP/cseqwrap"; mkdir -p "$d"
  for s in a b; do
    mk "$d/$s.log" 6 T1 "$s" PREPARE - - -; mk "$d/$s.log" 7 T1 "$s" COMMIT - 6 -
    mk "$d/$s.log" 0 T2 "$s" PREPARE - - -; mk "$d/$s.log" 1 T2 "$s" COMMIT - 7 -; done
  check 8 0 $'6\tT1\t\t\n7\tT2\t\t' "$d/a.log" "$d/b.log"; }
CASE="commit sequences exactly half a modulus apart are rejected"
{ d="$TMP/half"; mkdir -p "$d"
  mk "$d/a.log" 0 T1 a COMMIT - 0 -; mk "$d/a.log" 1 T2 a COMMIT - 4 -
  expect_rc 8 1 "$d/a.log"; }
CASE="dependency violated by commit order is rejected"
{ d="$TMP/depbad"; mkdir -p "$d"
  mk "$d/a.log" 0 T1 a COMMIT - 1 -; mk "$d/a.log" 1 T2 a COMMIT T1 0 -
  expect_rc 65536 1 "$d/a.log"; }
CASE="same commit sequence assigned to two txns is rejected"
{ d="$TMP/cseqdup"; mkdir -p "$d"
  mk "$d/a.log" 0 T1 a COMMIT - 3 -; mk "$d/a.log" 1 T2 a COMMIT - 3 -
  expect_rc 65536 1 "$d/a.log"; }
CASE="committed txn depending on a non-committed txn is rejected"
{ d="$TMP/depuncommitted"; mkdir -p "$d"
  mk "$d/a.log" 0 T0 a PREPARE - - -; mk "$d/a.log" 1 T0 a COMMIT - 0 -
  mk "$d/b.log" 0 T0 b PREPARE - - -
  mk "$d/a.log" 2 T1 a PREPARE - - -; mk "$d/a.log" 3 T1 a COMMIT T0 1 -
  expect_rc 65536 1 "$d/a.log" "$d/b.log"; }
CASE="valid record after a corrupt record (media corruption) is rejected"
{ d="$TMP/midcor"; mkdir -p "$d"
  mk "$d/a.log" 0 T1 a COMMIT - 5 -
  printf 'W1|1|T2|a|COMMIT|-|6|-|12345\n' >> "$d/a.log"
  mk "$d/a.log" 2 T3 a COMMIT - 7 -; expect_rc 65536 1 "$d/a.log"; }
CASE="single torn final record is silently discarded"
{ d="$TMP/tailonly"; mkdir -p "$d"; mk "$d/a.log" 0 T1 a COMMIT - 5 -
  printf 'W1|1|T2|a|COMMI' >> "$d/a.log"
  check 65536 0 $'5\tT1\t\t' "$d/a.log"; }
CASE="recovery outputs are stable and re-recovery is a no-op"
{ d="$TMP/idem"; mkdir -p "$d"
  for s in a b; do
    mk "$d/$s.log" 0 T1 "$s" PREPARE - - -; mk "$d/$s.log" 1 T1 "$s" COMMIT - 0 -
    mk "$d/$s.log" 2 T2 "$s" PREPARE - - -; mk "$d/$s.log" 3 T2 "$s" COMMIT - 1 -; done
  sz=$(stat -c%s "$d/b.log"); truncate -s $((sz - 15)) "$d/b.log"
  "$W" --out "$d/r1" "$d/a.log" "$d/b.log" >/dev/null
  "$W" --out "$d/r2" "$d/r1/logs/a.log" "$d/r1/logs/b.log" >/dev/null
  if diff -q "$d/r1/recovered.state" "$d/r2/recovered.state" >/dev/null &&
     diff -q "$d/r1/logs/a.log" "$d/r2/logs/a.log" >/dev/null &&
     diff -q "$d/r1/logs/b.log" "$d/r2/logs/b.log" >/dev/null; then ok "$CASE"; else bad "$CASE"; fi; }
CASE="in-place repair truncates once and is idempotent"
{ d="$TMP/inplace"; mkdir -p "$d"
  mk "$d/a.log" 0 T1 a COMMIT - 0 -; mk "$d/a.log" 1 T2 a COMMIT - 1 -
  sz=$(stat -c%s "$d/a.log"); truncate -s $((sz - 12)) "$d/a.log"
  "$W" --out "$d/r1" --in-place "$d/a.log" >/dev/null; s1=$(stat -c%s "$d/a.log")
  "$W" --out "$d/r2" --in-place "$d/a.log" >/dev/null; s2=$(stat -c%s "$d/a.log")
  torn2=$(jq -r .torn_or_corrupt_tails "$d/r2/report.json")
  if [ "$s1" = "$s2" ] && [ "$torn2" = "0" ]; then ok "$CASE"; else bad "$CASE"; fi; }
printf '\n%d passed, %d failed\n' "$pass" "$fail"
[ "$fail" -eq 0 ]
```

### `tests/fuzz.py` (differential oracle) and `tests/verify.sh`

`tests/fuzz.py` generates random logs (commit order, dependencies, torn tails, duplicates, CRC corruption, cseq swaps) and compares the shell tool against an independent Python reference on *both* accept/reject and the recovered order. `tests/verify.sh` runs shellcheck + unit tests + fuzz:

```bash
#!/usr/bin/env bash
set -euo pipefail
cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.."
iters="${1:-300}"; seed="${2:-1}"
command -v shellcheck >/dev/null 2>&1 && shellcheck walrec.sh && echo "shellcheck: clean"
./tests/run_tests.sh
python3 tests/fuzz.py "$iters" "$seed"
echo "ALL VERIFICATIONS PASSED"
```

